"""Compare fresh direct clips with installed Bill; no runtime writes."""
import json
from pathlib import Path
import numpy as np
from PIL import Image, ImageDraw

P=Path(__file__).resolve().parent
runtime=P.parent/'crew-runtime-matte-v1/bill'
m=json.loads((runtime/'manifest.json').read_text())
tracks=[]; reports={}
for direction in ['east','south']:
    old=next(s for s in m['states'] if s['id']=='walk-'+direction)
    tracks.append(dict(label=direction.title()+' - installed',files=['../crew-runtime-matte-v1/bill/'+f for f in old['frameFiles']],durations=old['frameDurationsMs']))
    root=P.parent/f'bill-{direction}-direct-v1'
    c=json.loads((root/'checks.json').read_text())
    tracks.append(dict(label=direction.title()+' - new full take',files=[f'../bill-{direction}-direct-v1/frames/walk-{direction}/{i:03}.png' for i in range(c['sourceFrames'])],durations=[1000/c['fps']]*c['sourceFrames']))
    bounds=c['bounds'];heights=[b[3]-b[1] for b in bounds]; med=np.array(c['neutralMedians'])
    reports[direction]=dict(frames=c['sourceFrames'],fps=c['fps'],firstLastHeight=[heights[0],heights[-1]],heightRange=[min(heights),max(heights)],clippedFrames=sum(b[0]<=0 or b[1]<=0 or b[2]>=184 or b[3]>=184 for b in bounds),neutralMedianRange=[med.min(0).tolist(),med.max(0).tolist()],loopSelected=False,installed=False,estimatedUSD=.19)
reports['cost']={'thisTurnEstimatedUSD':.38,'directTotalEstimatedUSD':.76,'actualBillingVerified':False}
(P/'validation.json').write_text(json.dumps(reports,indent=2)+'\n')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bill east and south - new takes</title><style>body{background:#172226;color:#dbe4df;font:17px system-ui;max-width:1150px;margin:24px auto;padding:16px}canvas{display:block;width:100%;height:auto;background:#303b40}img,video{max-width:100%}video{width:100%}button,select,input{font:inherit;padding:6px}a{color:#91d6d1}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.pair{display:grid;grid-template-columns:1fr 1fr;gap:20px}@media(max-width:650px){.pair{grid-template-columns:1fr}}</style><h1>Bill east and south - new takes</h1><p>Two direct Hailuo generations from the approved directional masters. Existing matte finish, fixed reference scale and registration. Candidate sources only: no selected loops and no game changes.</p><p>The new takes play their full source timing; installed walks repeat their existing 1.5-second loops. A restart of a new take is not a finished loop seam.</p><div class="controls"><button id="toggle">Pause</button><label>Speed <select id="speed"><option value="1">Normal</option><option value="0.5">Half</option></select></label><label>Time <input id="phase" type="range" min="0" max="5874" value="0"></label><span id="status">Loading frames...</span></div><p>Scale check: east starts/ends at 148/147px; south at 147/138px. South still shows some size drift. These measurements include step height variation; judge the complete motion below.</p><h2>Current and new at game scale</h2><p>Rows: 148px inspection height, then approximately 82 / 54 / 27px gameplay heights.</p><canvas id="board" width="920" height="540"></canvas><div class="pair"><section><h2>East original source</h2><video src="../bill-east-direct-v1/source.mp4" controls loop muted playsinline preload="metadata"></video><h3>East sampled frames</h3><img src="../bill-east-direct-v1/contact.png"></section><section><h2>South original source</h2><video src="../bill-south-direct-v1/source.mp4" controls loop muted playsinline preload="metadata"></video><h3>South sampled frames</h3><img src="../bill-south-direct-v1/contact.png"></section></div><p>Estimated US$0.38 for these two takes. Higgsfield balance and reserved motion-transfer run untouched.</p><p><a href="../bill-north-loop-v3/">North loop candidate</a></p><script>const tracks=TRACKS;let loaded=false,playing=true,t=0,last=0;const canvas=document.getElementById('board'),ctx=canvas.getContext('2d'),phase=document.getElementById('phase'),status=document.getElementById('status');Promise.all(tracks.map(async s=>{s.images=await Promise.all(s.files.map(src=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=()=>reject(src);im.src=src})));s.total=s.durations.reduce((a,b)=>a+b,0)})).then(()=>{loaded=true;status.textContent='All frames loaded'}).catch(e=>status.textContent='Image failed: '+e);document.getElementById('toggle').onclick=e=>{playing=!playing;e.target.textContent=playing?'Pause':'Play'};phase.oninput=()=>{t=Number(phase.value);playing=false;document.getElementById('toggle').textContent='Play'};function draw(now){if(last&&playing)t=(t+(now-last)*Number(document.getElementById('speed').value))%5875;last=now;if(loaded){ctx.clearRect(0,0,920,540);ctx.imageSmoothingEnabled=true;tracks.forEach((s,c)=>{let local=t%s.total,i=0;while(i<s.images.length-1&&local>=s.durations[i]){local-=s.durations[i++]}ctx.fillStyle='#dbe4df';ctx.font='14px system-ui';ctx.fillText(s.label,c*230+8,22);[148,82,54,27].forEach((height,row)=>{const side=184*height/148;ctx.drawImage(s.images[i],c*230+(230-side)/2,[38,245,368,457][row],side,side)})});phase.value=Math.floor(t)}requestAnimationFrame(draw)}requestAnimationFrame(draw);</script></html>'''
(P/'index.html').write_text(html.replace('TRACKS',json.dumps(tracks)),encoding='utf-8')
print(json.dumps(reports))
